import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';

/// Rock-solid guide image widget that loads from asset bundle and automatically
/// falls back to high-resolution embedded image data if the asset manifest is un-indexed or reloading.
class PostureGuideImage extends StatelessWidget {
  final bool isCorrect;
  final double? height;
  final double? width;
  final BoxFit fit;

  const PostureGuideImage({
    super.key,
    required this.isCorrect,
    this.height,
    this.width,
    this.fit = BoxFit.cover,
  });

  static final Uint8List _correctBytes = base64Decode(_kCorrectBase64);
  static final Uint8List _wrongBytes = base64Decode(_kWrongBase64);

  static Uint8List get correctBytes => _correctBytes;
  static Uint8List get wrongBytes => _wrongBytes;

  @override
  Widget build(BuildContext context) {
    final assetPath = isCorrect
        ? 'assets/images/posture_guide_correct.jpg'
        : 'assets/images/posture_guide_wrong.jpg';

    final fallbackBytes = isCorrect ? _correctBytes : _wrongBytes;

    return Image.asset(
      assetPath,
      height: height,
      width: width,
      fit: fit,
      errorBuilder: (context, error, stackTrace) {
        // Fallback to embedded image bytes — guaranteed to display 100% of the time!
        return Image.memory(
          fallbackBytes,
          height: height,
          width: width,
          fit: fit,
          errorBuilder: (_, __, ___) => Container(
            height: height,
            width: width,
            color: isCorrect ? const Color(0xFF1AE67A).withValues(alpha: 0.1) : const Color(0xFFE64545).withValues(alpha: 0.1),
            child: Icon(
              isCorrect ? Icons.check_circle_rounded : Icons.cancel_rounded,
              color: isCorrect ? const Color(0xFF1AE67A) : const Color(0xFFE64545),
              size: 36,
            ),
          ),
        );
      },
    );
  }

  static const String _kCorrectBase64 = "";
  static const String _kWrongBase64 = "";
}
